<script setup>
const props = defineProps({ document: Object, marks: { type: Array, default: () => [] }, fields: { type: Array, default: () => [] }, readonly: Boolean, reveal: Boolean })
const emit = defineEmits(['toggle'])
const columns = [['sequence','序号'],['zone','库区'],['locationCode','储位'],['productName','货品名称'],['sku','货品编号'],['specification','规格'],['expectedCartons','应放数量'],['actualCartons','实放数量'],['unit','单位'],['remarks','备注']]
const marked = (row, field) => props.marks.some(m => m.rowId === row && m.fieldKey === field)
const errorCell = (row, field) => props.reveal && props.document.errorCells?.find(m => m.rowId === row && m.fieldKey === field)
</script>
<template><section class="allocation-document"><h2>储位分配单</h2><div class="document-header"><span>作业单号：{{ document.header.jobNumber }}</span><span>入库单号：{{ document.header.inboundNumber }}</span><span>仓库编号：{{ document.header.warehouse }}</span><span>仓管员：{{ document.header.keeper }}</span><span>日期：{{ document.header.date }}</span></div><div class="table-scroll"><table><thead><tr><th v-for="[key,label] in columns" :key="key">{{ label }}</th></tr></thead><tbody><tr v-for="row in document.rows" :key="row.rowId"><td v-for="[key,label] in columns" :key="key" :class="{ 'review-marked': marked(row.rowId,key), 'review-answer': errorCell(row.rowId,key) }"><button v-if="fields.includes(key)" class="review-cell" :disabled="readonly" :aria-pressed="marked(row.rowId,key)" :aria-label="`第${row.sequence}行 ${label} ${row[key]}`" @click="emit('toggle', {rowId: row.rowId, fieldKey: key})">{{ row[key] }}<strong v-if="marked(row.rowId,key)">⚑ 已标注</strong></button><span v-else>{{ row[key] }}</span><small v-if="errorCell(row.rowId,key)" class="error">实际错误 · 正确值：{{ errorCell(row.rowId,key).correctValue }}</small></td></tr></tbody></table></div><div class="actions"><span>制单人：{{ document.header.author }}</span><span>作业人：{{ document.header.operator }}</span></div></section></template>
